from common_r1 import *
from quality_r1 import *
from acceptance_r1 import accept
from bernstein_r1 import certify

def main():
 protect();selected=read(R/'04_repair_strategies/SELECTED_M1_LOCAL_TRIAL.json');tid=selected['trial_id'];local=np.load(R/'05_local_repair_trials'/tid/'LOCAL_PROTOTYPE.npz');m=dict(np.load(R/'00_integrity/baseline/mesh.npz'));old=m['xyz'].copy();m['xyz']=old.copy();m['xyz'][local['node_indices']]=local['new_coordinates'];boundary=np.unique(m['tri6']);assert np.array_equal(m['xyz'][boundary],old[boundary]);assert np.array_equal(m['xyz'][np.unique(m['tet10'][:,:4])],old[np.unique(m['tet10'][:,:4])]);affected=local['affected_element_indices']
 certificate=certify(m['xyz'][m['tet10'][affected]],affected,'M1_C1');table(R/'08_quadratic_quality/M1_C1_BERNSTEIN_BOUNDS.csv',certificate)
 folder=R/'06_recovered_M1/M1_C1';assert not folder.exists();ledgerpath=R/'14_reproducibility/FULL_CANDIDATE_LEDGER.json';ledger=read(ledgerpath) if ledgerpath.exists() else [];assert sum(z['mesh_level']=='M1' for z in ledger)<2;folder.mkdir(parents=True);entry=dict(UTC=now(),source_id=SID,candidate_id='M1_C1',protocol_version=VERSION,mesh_level='M1',strategy='S1',local_trial=tid,status='SAVED_PENDING_ACCEPTANCE');ledger.append(entry);write(ledgerpath,ledger)
 m['quality']=gmsh_quality(m['xyz'],m['tet10'],m['node_tags'],m['element_tags'],folder/'mesh.msh',m['tri6']);np.savez_compressed(folder/'mesh.npz',**m)
 result=accept(m,folder,original_boundary_identity=True,affected=affected);result['exact_local_Bernstein_positive_elements']=sum(z['exact_positive_Bernstein_bound'] for z in certificate);result['exact_local_Bernstein_elements']=len(certificate);result['exact_local_Bernstein_min_bound_mm3']=min(z['lower_detJ_mm3'] for z in certificate);write(folder/'PRE_SOLVER_QUALIFICATION.json',result)
 changes=[dict(candidate_id='M1_C1',node_index=int(i),original_Gmsh_node_tag=int(m['node_tags'][i]),old_X_mm=float(old[i,0]),old_Y_mm=float(old[i,1]),old_Z_mm=float(old[i,2]),new_X_mm=float(m['xyz'][i,0]),new_Y_mm=float(m['xyz'][i,1]),new_Z_mm=float(m['xyz'][i,2]),dX_mm=float(m['xyz'][i,0]-old[i,0]),dY_mm=float(m['xyz'][i,1]-old[i,1]),dZ_mm=float(m['xyz'][i,2]-old[i,2]),norm_mm=float(np.linalg.norm(m['xyz'][i]-old[i])),boundary=False,corner=False) for i in local['node_indices']];table(R/'LOCAL_NODE_DISPLACEMENTS.csv',changes)
 baseline=np.load(R/'08_quadratic_quality/ORIGINAL_GLOBAL_QUALITY.npz');new=np.load(folder/'GLOBAL_QUALITY.npz');table(R/'LOCAL_ELEMENT_QUALITY_BEFORE_AFTER.csv',[dict(candidate_id='M1_C1',element_index=int(e),Gmsh_element_tag=int(m['element_tags'][e]),before_SICN=float(baseline['quality'][e]),after_SICN=float(new['quality'][e]),before_minQ1_J_mm3=float(baseline['min_Q1_J'][e]),after_minQ1_J_mm3=float(new['min_Q1_J'][e])) for e in affected]);entry.update(status='QUALIFIED' if result['pre_solver_qualified'] else 'FAILED',mesh_SHA256=sha(folder/'mesh.npz'));write(ledgerpath,ledger);write(R/'06_recovered_M1/FINAL_M1.json',dict(candidate_id='M1_C1',status='C02_M1_QUALIFIED' if result['pre_solver_qualified'] else 'C02_M1_NOT_QUALIFIED',qualified=result['pre_solver_qualified'],receipt=str((folder/'PRE_SOLVER_QUALIFICATION.json').relative_to(R)),mesh_SHA256=sha(folder/'mesh.npz')));print('M1_FINAL',result,flush=True)
if __name__=='__main__':main()
